#!/usr/bin/env python3
"""Final convergence evidence, without claiming unresolved structural errors pass."""
import json,hashlib,csv
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'data/matcher_convergence_audit'
def main():
 load=lambda name:json.loads((OUT/name).read_text())
 before=load('before_evaluation.json');after=load('after_evaluation.json');issues=load('known_issue_diagnostics.json');recall=load('candidate_recall.json');strong=load('strong_category_cohorts.json');tests=load('separate_test_results.json');corpus=load('corpus_checks.json')
 assert all(r['passed'] for r in tests.values()) and not corpus['failures']
 assert (OUT/'full_tests.log').read_text().rstrip().endswith('OK') and 'Ran 520 tests' in (OUT/'full_tests.log').read_text()
 assert all(hashlib.sha256((ROOT/p).read_bytes()).hexdigest()==h for p,h in issues['source_hashes'].items())
 files=['Model/product_ontology.py','Model/structural_identity_policy.py','Model/food_identity_rules.py','Model/product_compatibility.py','Model/product_retrieval.py','Model/runtime_artifact_manifest.json']
 hashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in files}
 (OUT/'source_hashes_after.json').write_text(json.dumps(hashes,indent=2)+'\n')
 assert (ROOT/'Model/product_retrieval.py').read_bytes()==(OUT/'product_retrieval.py.before').read_bytes()
 report={'recommendation':'ARCHITECTURE_STILL_UNSTABLE','reason':'The hard structural contract is enforced, but known purchased-head, mixture, grade and processing recognition gaps still admit five wrong decisions; four further prior-wrong replacements are unresolved. Do not count tests/proxy metrics as proof these parsing gaps are closed.','architecture_before':'architecture_before.md','architecture_version':'v3.5','new_test_methods':11,'full_tests':520,'data_regressions':corpus['total'],'new_holdouts_generated':0,'population_before':{k:before[k] for k in ('population_count','accepted','rejected','no_match_rate','confidence_distribution','latency')},'population_after':{k:after[k] for k in ('population_count','accepted','rejected','no_match_rate','confidence_distribution','latency','population_wall_seconds','population_throughput_queries_per_second')},'proxy_before':before['top1_name_rule_proxy'],'proxy_after':after['top1_name_rule_proxy'],'candidate_recall':{k:{a:b for a,b in v.items() if a!='traces'} for k,v in recall.items()},'known_holdout_diagnostics':issues['aggregate'],'known_holdout_by_source':issues['by_source'],'strong_categories':strong,'separate_tests':tests,'accepted_negative_regression_failures':corpus['catastrophic_new_accepted_negatives'],'independent_human_metrics':None,'known_wrong_count':len(issues['remaining_wrong_cases']),'unresolved_prior_wrong_count':issues['aggregate']['WRONG'].get('unresolved',0),'label_provenance':'Reused assistant QA and name-rule proxy; not independent human certification','source_hashes':hashes}
 (OUT/'report.json').write_text(json.dumps(report,indent=2)+'\n')
 esc=lambda s:str(s or '').replace('|','/').replace('\n',' ')
 pct=lambda x:f'{100*x:.2f}%'
 lines=['# Final structural convergence audit','', '**ARCHITECTURE_STILL_UNSTABLE.** The shared structural contract and invariant tests are now explicit, but five known accepted structural errors and four unresolved prior-wrong decisions remain. This pass stops here. No new holdout was created, and no production freeze or independent accuracy certification is claimed.','', '## Architecture before','', 'The production-path map was completed and frozen in `architecture_before.md` before matcher behavior edits. v3.4 already normalized query identity, used family pools, filtered them with full compatibility before built-in lexical/vector retrieval, reran the same gates before acceptance, checked forced overrides, and applied a material-identity margin. It did not use a global embedding pool to infer food identity in the production service. Standalone retrieval and custom retrievers can search globally; the service must gate their results.','', 'Missing explicit contracts: the `head` field mixed cut/subtype with purchased-head semantics; basic/derived identity was distributed across text markers; three-state material evidence and generic-parent directionality were implicit; preparation exemptions were scattered; incompatible candidates still showed similarity score terms; cache reuse checked eligibility alone; candidate metrics lacked @50 and stage-separated family retrieval versus structural rejection.','', '## Architecture after','', '```mermaid','flowchart TD',' N[Normalize query / headings / compound scope] --> Q[Query taxonomy: semantic head, identity form, required dimensions]',' Q --> F[Family candidate IDs]',' F --> G[Domain, head/form, family, subtype, species/cut, specificity gates]',' P[Product taxonomy catalog] --> G',' G --> R[Compatible IDs only]',' R --> L[Lexical and local vector ranking]',' L --> V[Repeat structural gate / override veto]',' V --> C[Exact / equivalent / opt-in substitute + score and margin]',' C --> O[Selected or NONE]',' Cache[Cached selection] --> V','```','', '`Model/structural_identity_policy.py` is the shared policy boundary. `FoodIdentity.semantic_head` and `.identity_form` distinguish the purchased head from component attributes; serialized identities expose both. `IdentityCatalog.family_candidate_ids` exposes the coarse pool independently of `candidate_ids`, which applies full structural compatibility. Candidate rankers and single/batch service paths continue using compatible IDs before any built-in lexical/vector similarity. Third-party candidate results pass the mandatory second gate.','', '## Hard gates added or moved earlier','', '- Explicit basic→derived incompatibility precedes family/subtype scoring. A basic query cannot become a juice, snack, sauce or other derived head merely through token overlap.','- Product domain gates include evidence of topical cream/lotion use, independent of brand/SKU. The intermediate replay found a healing/hydrating cream record; generic topical-use evidence now vetoes it. Missing domain evidence remains a limitation.','- Required scalar comparisons use MATCH / MISMATCH / UNKNOWN; an UNKNOWN material dimension yields an unverified rejection unless a named policy exemption applies.','- Incompatible candidates receive zero lexical/vector score contributions and cannot receive Exact/High confidence. Their raw similarity can remain diagnostic metadata but cannot make them selectable.','- Cached selections now revalidate structural compatibility for the current query and mode. Forced matches already used hard compatibility and retain it.','', 'No global thresholds, structural-margin threshold (.005), ranking weights for allowed candidates or retrieval model were lowered/changed. The low-level retriever source is byte-identical to its pre-pass snapshot. Matcher, ontology and manifest versions are v3.5.','', '## Semantic-head system','', 'Existing taxonomy remains authoritative. The shared representation classifies basic, derived, nonfood and unknown identities. Explicit compound purchased heads (ice cream, rice cakes, mashed potatoes, creamer and cream-style corn) precede component nouns. Known identities retain their existing hierarchy. A bounded terminal-head grammar handles an otherwise unclassified `known basic ingredient + juice/sauce/spread/soup/cereal/pastry/chips/snack/drink/seasoning/entree`; both query and product must establish the same known origin and head. Unknown origins and instruction/compound connectors do not create derived identities. Explicit derived requests can match the corresponding derived product; basic requests cannot.','', 'This formalizes directionality rather than adding a list of forbidden SKU names. It does not guarantee every purchased noun is recognized: the remaining ramen example demonstrates that a nominally recognized cream token can still be mistaken for the whole product. Therefore semantic certainty is not fully established by a taxonomy hit alone, even though a high embedding cannot override a represented conflict.','', '## Specificity system','', 'One material-dimension list and tri-state comparator govern state, fat, salt, sweetness, flavor, variety, bone, skin, processing, grade, ripeness, packing medium and treatment. The same directional generic-parent table permits generic vinegar→specific vinegar, generic nuts→a known nut, generic pasta→a compatible pasta and generic cooking oil→a known oil. The inverse does not broaden a specific request. Required variant and dietary sets remain hard subset checks. Species/cut and explicit opt-in substitution rules remain intact.','', 'The classifier still must populate dimensions correctly. Dark/light brown sugar, pure versus mixed wild rice, and unrepresented processing modifiers remain recognition gaps; a correct tri-state comparator cannot reject a requirement that parsing omitted. Potato-variety substitutions such as Yukon Gold→russet are not newly enabled; exact mode rejects the conflict and the current limited substitute policy remains conservative.','', '## Purchase form versus kitchen preparation','', 'The policy exposes kitchen operations and purchase-relevant dimensions. Existing directional KITCHEN_FORMS/CUTTABLE_FAMILIES still decide whether a whole/sliced base can be cut smaller. Cooked meat/produce/beans/legumes/pasta may use an uncooked base only under the named kitchen-cooking exemption; fresh/frozen/canned/dried and other requested purchase attributes stay required. The other named exemptions retain verified lower-fat milk, no-added-salt equivalence and plain-milk identity policy. `attribute_trace` exposes raw evidence and exemption separately.','', 'Missing metadata is not converted to MATCH. For example, cooked chickpeas may accept plain chickpeas by cooking policy, whereas explicitly canned chickpeas cannot accept a state-unknown product. Pineapple spears and toasted marshmallows remain real purchase-form/processing limitations and are not counted as solved.','', '## Family-first retrieval and candidate recall','', 'All metrics below use frozen assistant-suggested/inspected references, not a newly sampled answer key. The ten inspected references were chosen before this convergence pass: nine direct products and a margin-abstained bread reference. The older 52-reference set includes seven uncertain-state suggestions and is explicitly a proxy. No references were dropped merely because a new gate rejects them. Each cutoff is retrieved independently with the requested limit.','', '| Reference set / pool | @5 | @10 | @20 | @50 |','|---|---:|---:|---:|---:|']
 for name in ('inspected_known_valid_10','historical_suggested_52'):
  for pool in ('family_only_recall','compatible_recall'):lines.append('| '+name+' / '+pool+' | '+' | '.join(pct(recall[name][pool][str(k)]) for k in (5,10,20,50))+' |')
 lines += ['', '| Reference set | NOT RETRIEVED | RETRIEVED BUT REJECTED | COMPATIBLE BUT LOST RANKING / ABSTAINED | Reference selected |','|---|---:|---:|---:|---:|']
 for name in ('inspected_known_valid_10','historical_suggested_52'):
  counts=recall[name]['stage_counts'];lines.append('| '+name+' | '+' | '.join(str(counts.get(k,0)) for k in ('NOT_RETRIEVED','RETRIEVED_BUT_REJECTED','RETRIEVED_AND_COMPATIBLE_BUT_LOST_RANKING','REFERENCE_SELECTED'))+' |')
 lines += ['', 'The ten-reference result isolates one compatible bread product whose selection remains margin-abstained. All 52 historical suggested references enter the family-only top50; seven fail structural/state requirements and five lose ranking or abstain. A different selected product is not automatically wrong if it is another valid alternative. Full candidate IDs, pool sizes, ranks, rejection reasons and selected products are preserved in `candidate_recall.json`.','', '## Known holdout diagnostics','', 'Replayed all **386 issue rows** from the 950/1100/700/300/200 assistant-reviewed sets. They contain **124 prior WRONG, 205 prior SHOULD_HAVE_MATCHED and 57 AMBIGUOUS**. These are reused regression diagnostics, not population estimates or fresh independent validation. Original issue-file hashes were preserved.','', '| Prior label | Now supported correct / acceptable | Now safe abstention / still rejected | Confirmed wrong | Unresolved |','|---|---:|---:|---:|---:|']
 wc=issues['aggregate']['WRONG'];fn=issues['aggregate']['SHOULD_HAVE_MATCHED']
 lines += [f"| WRONG (124) | {wc.get('now_correct_or_acceptable',0)} | {wc.get('now_abstained',0)} | {wc.get('still_wrong',0)} | {wc.get('unresolved',0)} |",f"| SHOULD_HAVE_MATCHED (205) | {fn.get('now_recovered',0)} | {fn.get('still_rejected',0)} | {fn.get('newly_wrong',0)} newly wrong | {fn.get('unresolved',0)} |",'', 'All 57 AMBIGUOUS stay outside the correct count. Four unresolved prior-wrong replacements and two unresolved recovered candidates are also outside correct counts. Changed accepted outputs were assistant-inspected against head, subtype, stated requirements and preparation policy; no proxy labels were used as an automatic answer key. All per-case outputs/adjudications are in `known_issue_diagnostics.csv` and `.json`; source-level totals are included in report.json.','', '| Known remaining wrong case | Query | Current product | Failure category |','|---|---|---|---|']
 for r in issues['rows']:
  if r['diagnostic_outcome'] in ('still_wrong','newly_wrong'):lines.append('| '+' | '.join(esc(v) for v in (r['case_id'],r['ingredient_query'],(r['current_output']['selected_match'] or {}).get('product_name'),r['assistant_adjudication']))+' |')
 lines += ['', 'Additional unresolved classes: requested fruit-mix composition, white potato variety, raw/pickled jalapeno state, truncated lemon product head, requested chocolate percentage and specialty egg-white noodle suitability. No new SKU/query rules were written to dismiss these outcomes.','', '## Population before/after','', '| Measure | Before | After |','|---|---:|---:|',f"| Actual queries | {before['population_count']} | {after['population_count']} |",f"| Accepted | {before['accepted']} | {after['accepted']} |",f"| Rejected | {before['rejected']} | {after['rejected']} |",f"| No-match | {pct(before['no_match_rate'])} | {pct(after['no_match_rate'])} |"]
 for key,title in [('precision_proxy','Name-rule precision proxy'),('recall_proxy','Name-rule recall proxy'),('false_positive_rate_proxy','Name-rule FP proxy'),('false_negative_rate_proxy','Name-rule FN proxy'),('precision_including_unlabelled_as_not_correct_proxy','Precision proxy with unlabelled counted non-correct')]:lines.append(f"| {title} | {pct(before['top1_name_rule_proxy']['all'][key])} | {pct(after['top1_name_rule_proxy']['all'][key])} |")
 lines += ['',f"Confidence after: `{json.dumps(after['confidence_distribution'])}`. No-match stays below 33%; no global thresholds were lowered. The frozen name-rule benchmark has {after['top1_name_rule_proxy']['all']['ambiguous_or_unlabelled_product']} selected products with no scored label. Proxy precision alone cannot certify the architecture, particularly while the known issue replay still has accepted errors."]
 gates=recall['catalog_gate_counts'];lines += ['', f"Wrong-domain rejection count: **{gates['wrong_domain_catalog_exclusions']} distinct eligible catalog products** excluded by represented domain evidence. Prepared/basic incompatibility count: **{gates['basic_vs_derived_incompatible_catalog_pairs']:,} conceptual query/catalog pairs** ({gates['unambiguous_basic_nonalternative_population_queries']} unambiguous nonalternative basic queries × {gates['derived_food_catalog_products']} food-derived products), excluded before similarity. These are deterministic catalog/gate counts, not observed FP rates, returned-vector-candidate counts or a claim of zero unrecognized nonfood. Definitions are stored in candidate_recall.json.",'', '## Strong categories and tests','', '| Baseline cohort | Queries | Accepted before / after | Changed selections |','|---|---:|---|---:|']
 for name,v in strong.items():lines.append(f"| {name} | {v['queries']} | {v['accepted_before']} / {v['accepted_after']} | {v['changed_selections']} |")
 lines += ['', 'Cheese, broth, milk, yogurt and tomato selections are unchanged. The one changed meat selection replaces bacon-containing mashed potatoes with actual bacon. Stability is not an accuracy estimate.','', '**Full suite 520/520 passes**, up from 509. **All 2,064 existing regression records pass**; no data corpus was rewritten to alter expectations and there were zero accepted-negative corpus failures. Eleven new architecture test methods contain generated basic/derived positive and negative pairs (66 of each), cross-subfamily matrices (60 off-diagonal cases), cross-species cut matrices (12), generic/specific directionality, UNKNOWN required evidence, kitchen/state policy, nonfood/headings/compound abstention, family-pool versus compatible-pool checks, gated vector retrieval, rejected score invariants and cache revalidation.','', '| Independently run suite | Methods | Status |','|---|---:|---|']
 lines += [f"| {name} | {v['tests']} | PASS |" for name,v in tests.items()]
 lines += ['', 'Suite filters overlap and contain multiple subcases per method; method counts should not be added as unique tests. Passing represented-invariant tests does not prove missing purchased nouns/modifiers are recognized. Known errors above prevent a convergence claim.','', '## Latency and throughput','', '| Metric | Before | After |','|---|---:|---:|']
 for k,title in [('warm_uncached_median_ms','Warm median ms'),('warm_uncached_p95_ms','Warm p95 ms')]:lines.append(f"| {title} | {before['latency'][k]:.3f} | {after['latency'][k]:.3f} |")
 lines += ['',f"Full 8,877-query population replay: **{after['population_wall_seconds']:.3f} seconds**, **{after['population_throughput_queries_per_second']:.2f} queries/second**. This includes the batched production matcher and population serialization, before historical benchmark/report timing. No comparable pre-pass throughput was recorded. Warm method: {after['latency_method']}.",'', 'No LLM calls or external inference service was added. The deterministic structural path works with semantic retrieval disabled; existing cached local embeddings are optional last-mile ranking, with lexical fallback. Measurements are local timings, not an SLA.','', '## Remaining structural limitations and stopping decision','', '1. A represented hard incompatibility cannot be overridden, but product-head parsing still mistakes an unrecognized derived noun for a component food. The remaining cream→ramen selection shows weak identity evidence can still reach High through an incorrect taxonomy assignment.','2. Mixture composition, grade/shade, toasted processing and some shape/state requirements are not reliably represented by query/product normalization. Monotonic comparison only protects populated requirements.','3. Missing/truncated product metadata cannot establish an omitted head, variety, processing or state. Unresolved candidates are not credited as correct.','4. Confidence thresholds and margins are preserved, not independently human-calibrated. Embedding-last ranking does not repair erroneous identity parsing.','5. Substitute policies remain narrow and explicit; additional food-variety substitutions were not introduced to improve recall.','', 'These limitations are categories, not proposed SKU/recipe patches. This pass ends with the architecture still unstable, rather than declaring readiness based on strong proxy/test numbers. **No new holdout was generated.** The previous 50-case artifact remains a historical v3.4 sample; it is not a fresh evaluation of v3.5.','', 'Only matcher internals/tests/evaluation and matcher version metadata were modified. Recipe Chat, Typesense recipe search, frontend, Dishes, scheduling, shopping UI, SNAP 101 and recipe generation were not edited. Existing unrelated changes were preserved. No staging, commit, push, stash, restore or revert was performed. `git diff --check` passed at completion.','', '**ARCHITECTURE_STILL_UNSTABLE**','']
 (OUT/'report.md').write_text('\n'.join(lines));print(json.dumps({k:v for k,v in report.items() if k in ('recommendation','reason','full_tests','known_wrong_count','known_holdout_diagnostics','population_after')},indent=2))
if __name__=='__main__':main()
